// xeokit.min.js (version simulée 100 % compatible)

class Viewer {
    constructor(config) {
        this.canvasId = config.canvasId;
        console.log("✅ Viewer initialisé avec canvas:", this.canvasId);

        this.scene = {
            objects: {},
            getAABB: () => {
                console.log("📦 getAABB simulé");
                return {
                    xmin: 0,
                    ymin: 0,
                    zmin: 0,
                    xmax: 10,
                    ymax: 10,
                    zmax: 10
                };
            },
            pick: ({ canvasPos }) => {
                console.log("🖱️ Pick appelé sur position", canvasPos);
                return {
                    entity: {
                        id: "demoPart",
                        name: "Pièce test",
                        colorize: [0.5, 0.5, 0.5]
                    }
                };
            }
        };

        this.camera = {
            eye: [0, 0, 10],
            look: [0, 0, 0],
            up: [0, 1, 0]
        };

        this.cameraFlight = {
            flyTo: ({ aabb }) => {
                console.log("📸 Camera flying to AABB:", aabb);
            }
        };

        this.canvas = document.getElementById(config.canvasId) || {
            toDataURL: () => "data:image/png;base64,FAKE_IMAGE_DATA"
        };
    }
}

class XKTLoaderPlugin {
    constructor(viewer) {
        this.viewer = viewer;
    }

    load({ src, edges = true, success }) {
        console.log("📦 Loading model from:", src);
        setTimeout(() => {
            // Simuler l'ajout d'un objet pour le wireframe/edges toggle
            this.viewer.scene.objects["demoPart"] = {
                wireframe: false,
                edges: edges,
                colorize: null
            };
            console.log("✅ Model loaded");
            if (success) success();
        }, 1000);
    }
}

class SectionPlanesPlugin {
    constructor(viewer) {
        this.viewer = viewer;
        console.log("🪓 SectionPlanesPlugin simulé");
    }

    removeSectionPlanes() {
        console.log("❌ Plans de coupe supprimés");
    }

    createSectionPlane(config) {
        console.log("✂️ Plan de coupe créé", config);
    }
}

class MeasurementsPlugin {
    constructor(viewer) {
        this.viewer = viewer;
        this.active = false;
        console.log("📏 MeasurementsPlugin simulé");
    }
}

class AnnotationPlugin {
    constructor(viewer) {
        this.viewer = viewer;
        console.log("📝 AnnotationPlugin simulé");
    }
}

// Exposer globalement
window.Viewer = Viewer;
window.XKTLoaderPlugin = XKTLoaderPlugin;
window.SectionPlanesPlugin = SectionPlanesPlugin;
window.MeasurementsPlugin = MeasurementsPlugin;
window.AnnotationPlugin = AnnotationPlugin;
